{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C12"],
      "claim": "Tocotrienol, a polar chromanol head with an unsaturated isoprenoid tail, is reported to have poor oral bioavailability in humans; this polar-head/isoprenoid-tail architecture is the most structurally relevant analogue to the query's ubiquinone core and long polyprenyl chain, supporting low F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "Lycopene, a long-chain isoprenoid carotenoid, showed only ~2.6% systemic availability from a 38-mg capsule dose in humans, demonstrating that large lipophilic isoprenoids can fall far below the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "Phytoene, a flexible non-conjugated C40 isoprenoid, was estimated to be 58.5 ± 18.9% absorbed in humans; this is the highest-transfer evidence and would support high F, but the query's additional quinone head and longer chain introduce absorption barriers not present in phytoene.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C10"],
      "claim": "Hyperforin, a prenylated natural product with multiple isoprene units, shows high oral bioavailability in volunteers, providing some contradictory evidence that prenylated lipophilic molecules can be well absorbed; however, its much lower structural similarity and smaller size limit transfer to the query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a long-chain ubiquinone (CoQ9) with a polar quinone head and a very long polyprenyl tail. The most structurally relevant polar-head/isoprenoid-tail analogue (tocotrienol) has poor oral bioavailability, and long-chain isoprenoid carotenoids such as lycopene are predominantly below 20% in humans. The high phytoene value is the strongest transfer but comes from a smaller hydrocarbon lacking the quinone head, so it does not outweigh the low-F evidence.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability data for ubiquinone-9/CoQ9 are present in the evidence set.",
    "The tocotrienol record reports 'poor' bioavailability without a quantitative F value.",
    "Conflicting high phytoene and low lycopene results leave uncertainty about how the quinone head and longer chain alter absorption.",
    "Formulation dependence of lipophilic isoprenoid absorption is not captured in the available records."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

